-- Reconciliation checkpoints (docs/domain-model.md §2): "on date D this account
-- really held X", with the adjustment that made the ledger agree (NULL when it
-- already did).
--
-- Purely additive: CREATE TABLE + indexes only. No table is rebuilt, so unlike
-- 0002 this needs no view drop/recreate and no foreign-key guard. Generated by
-- drizzle-kit and reviewed unchanged (docs/tech-stack.md §9).
--
-- There is deliberately no unique index on (owner_id, account_id, as_of): a
-- checkpoint is a historical observation, and an account may be verified more
-- than once on the same day.

CREATE TABLE `reconciliation_checkpoints` (
	`id` text PRIMARY KEY NOT NULL,
	`owner_id` text NOT NULL,
	`account_id` text NOT NULL,
	`as_of` text NOT NULL,
	`stated_balance_minor` integer NOT NULL,
	`adjustment_id` text,
	`created_at` text NOT NULL,
	`updated_at` text NOT NULL,
	FOREIGN KEY (`owner_id`) REFERENCES `owners`(`id`) ON UPDATE no action ON DELETE restrict,
	FOREIGN KEY (`owner_id`,`account_id`) REFERENCES `accounts`(`owner_id`,`id`) ON UPDATE no action ON DELETE restrict,
	FOREIGN KEY (`owner_id`,`adjustment_id`) REFERENCES `transactions`(`owner_id`,`id`) ON UPDATE no action ON DELETE restrict,
	CONSTRAINT "ck_reconciliation_checkpoints_as_of" CHECK(date("reconciliation_checkpoints"."as_of") IS NOT NULL AND "reconciliation_checkpoints"."as_of" = date("reconciliation_checkpoints"."as_of")),
	CONSTRAINT "ck_reconciliation_checkpoints_stated_integer" CHECK(typeof("reconciliation_checkpoints"."stated_balance_minor") = 'integer')
);
--> statement-breakpoint
CREATE UNIQUE INDEX `ux_reconciliation_checkpoints_owner_id` ON `reconciliation_checkpoints` (`owner_id`,`id`);--> statement-breakpoint
CREATE INDEX `ix_reconciliation_checkpoints_account_as_of` ON `reconciliation_checkpoints` (`owner_id`,`account_id`,`as_of`);--> statement-breakpoint
CREATE INDEX `ix_reconciliation_checkpoints_adjustment` ON `reconciliation_checkpoints` (`owner_id`,`adjustment_id`) WHERE "reconciliation_checkpoints"."adjustment_id" IS NOT NULL;